\label{asm:loss-regularity}
The training loss $\ell:\mathbb{R}\to\mathbb{R}$ is convex and is either globally Lipschitz or the squared loss $\ell(r)=r^2/2$.
Assume
\begin{align}
  \operatorname*{argmin}_{r\in\mathbb{R}}
  \mathbb{E}_\epsilon\ell\ab(r-\epsilon)
  &=
  \{0\},
  \quad
  0
  <
  \left.
  \frac{\mathrm d^2}{\mathrm d r^2}
  \mathbb{E}_\epsilon\ell\ab(r-\epsilon)
  \right|_{r=0}
  <\infty.
  \label{eq:noise-averaged-training-loss}
\end{align}

\label{prop:test-prediction-generalization}
  Let $0<\alpha<2$ and $S_\alpha\sim S\alpha S(1)$.
  Then, the asymptotic generalization error \eqref{eq:generalization-error} is given by
  \begin{align}
    \mathcal E_{N,D}^{(\alpha)}
    \xrightarrow{\mathrm p}
    \mathcal E^{(\alpha)}(\kappa)
    :=
    \mathbb{E}_{S_\alpha,\epsilon_0}
    \ab[
      \ell_{\mathrm{test}}
      \ab(
        q_\alpha^{1/\alpha}S_\alpha-\epsilon_0
      )
    \ab].
    \label{eq:limiting-stable-generalization-error}
  \end{align}

\label{res:learned-parameter-statistics}
  With $\mathbb{E}\left|\hat u\right|^{\alpha}<\infty$, the empirical coefficient distribution and its $\alpha$-moment satisfy
  \begin{align}
    &\hat w_i-w_i^*
    \xrightarrow{\mathrm d}
    \hat u \label{eq:learned-empirical-law-main}
    \\
    &q_{\alpha,D}
    \xrightarrow{\mathrm p}
    q_\alpha
    :=
    \mathbb{E}\left|\hat u\right|^{\alpha},
    \label{eq:learned-empirical-law-main_q}
  \end{align}
  where the expectation is over the joint distribution of $\zeta$, $\hat{\mathcal R}$, $\hat Q$, and $w^*$.

\label{prop:gaussian-universality}
  Let the feature coordinates be i.i.d. from a sub-Gaussian distribution $P_X$ satisfying
  $\mathbb{E}_{P_X}X=0$ and $\mathbb{E}_{P_X}X^2=1$, 
  and suppose that Assumption~\ref{asm:loss-regularity} holds with $\alpha=2$.
  Let $q_2^{P_X}$ and $q_2^{\mathrm G}$ denote the limiting coefficient-error
  moments under $P_X$ and standard Gaussian features, respectively.
  Then
  \begin{align}
    q_2^{P_X}
    &=q_2^{\mathrm G}.
    \label{eq:gaussian-coefficient-error-universality}
  \end{align}

\label{res:heavy-tail-universality}
  Let $0<\alpha<2$, and let the feature coordinates be i.i.d. from a symmetric distribution $P_X$ satisfying
  \begin{align}
    \Pr\ab(\left|X\right|>x)
    &=C_\alpha^{\mathrm S}x^{-\alpha}+o\ab(x^{-\alpha})
    \qquad (x\to\infty),
    \label{eq:stable-domain-universality-tail}
  \end{align}
  where $C_\alpha^{\mathrm S} := 2\Gamma(\alpha)\sin(\pi\alpha/2) / \pi$ is the total tail constant of $S\alpha S(1)$
  \footnote{If the original distribution has a total tail constant $C>0$, rescaling $X$ by $(C_\alpha^{\mathrm S}/C)^{1/\alpha}$ recovers this normalization; equivalently, the original distribution is compared against $S\alpha S((C/C_\alpha^{\mathrm S})^{1/\alpha})$.},
  and suppose that Assumption~\ref{asm:loss-regularity} holds.
  Let $q_\alpha^{P_X}$ and $q_\alpha^{\mathrm S}$ denote the limiting
  coefficient-error moments under $P_X$ and $S\alpha S(1)$ features,
  respectively.
  Then
  \begin{align}
    q_\alpha^{P_X}
    &=q_\alpha^{\mathrm S}.
    \label{eq:stable-coefficient-error-universality}
  \end{align}

\label{res:data-rich-tail-reliability}
  Suppose that Assumption~\ref{asm:loss-regularity} holds.
  Let $\Delta^{(2)}(\kappa)$ denote the Gaussian counterpart of
  $\Delta^{(\alpha)}(\kappa)$ in
  Equation~\eqref{eq:noise-free-pred^error}.
  Then, for every $0<\alpha<2$, there exists a constant
  $c_\alpha\in(0,\infty)$ such that
  \begin{align}
    q_\alpha(\kappa)
    =
    \frac{c_\alpha}{\kappa}
    +o(\kappa^{-1}),
    \qquad
    \kappa\to\infty.
    \label{eq:data-rich-coefficient-error}
  \end{align}
  Consequently, for every fixed $t>0$,
  \begin{align}
    \operatorname{median}\ab(
      \left|\Delta^{(\alpha)}(\kappa)\right|
    )
    =
    \Theta\ab(\kappa^{-1/\alpha}),
    \quad
    \Pr\ab(
      \left|\Delta^{(\alpha)}(\kappa)\right|>t
    )
    =
    \Theta\ab(\kappa^{-1}).
    \label{eq:data-rich-fixed-threshold-failure}
  \end{align}
  For Gaussian features,
  \begin{align}
    \operatorname{median}\ab(
      \left|\Delta^{(2)}(\kappa)\right|
    )
    =
    \Theta\ab(\kappa^{-1/2}),
    \quad
    \Pr\ab(
      \left|\Delta^{(2)}(\kappa)\right|>t
    )
    =
    \exp[-\Theta(\kappa)],
    \label{eq:data-rich-fixed-threshold-failure-gauss}
  \end{align}
  where $f=\Theta(g)$ means that $f$ and $g$ have the same asymptotic
  order up to constant factors.

\label{res:bayes-optimal-error}
  The coefficient error satisfies
  \begin{align}
    q_{\alpha,\mathrm B}&\ab(\kappa)
    =
    \frac{
      2^{\alpha/2}\Gamma\ab((\alpha+1)/2)\sigma^\alpha
    }{
      \sqrt\pi\,\Gamma\ab(1+\alpha/2)
    }\notag \\
    &\quad \times 
    \int_0^\infty
    \exp\Bigg\{
      -\frac{\sigma^2}{\tau^2}u^{\frac{2}{\alpha}}
      -\frac{
        \kappa 2^\alpha\Gamma\ab(\frac{\alpha+1}{2})
      }{
        \sqrt\pi\,\Gamma\ab(1+\alpha/2)
      }
      u
      \int_0^\infty
      \exp\ab(
        -v^{\frac{2}{\alpha}}
        -\frac{
          2^{\frac{\alpha}{2}}q_{\alpha,\mathrm B}\ab(\kappa)
        }{
          \sigma^\alpha
        }v
      \ab)
      \,\mathrm dv
    \Bigg\}
    \,\mathrm du.
    \label{eq:bayes-optimal-alpha-error-fixed-point}
  \end{align}
  In particular, expanding
  Equation~\eqref{eq:bayes-optimal-alpha-error-fixed-point} for large
  $\kappa$ gives
  \begin{align}
    q_{\alpha,\mathrm B}\ab(\kappa)
    &=
    \frac{2^{-\alpha/2}}{\Gamma\ab(1+\alpha/2)}
    \frac{\sigma^\alpha}{\kappa}
    +o\ab(\kappa^{-1}).
    \label{eq:bayes-optimal-alpha-error}
  \end{align}

\label{res:iid-elliptical-bayes-comparison}
  For $0<\alpha<2$ and $\kappa>0$,
  \begin{align}
    q_{\alpha,\mathrm B}\ab(\kappa)
    &<
    q_{\alpha,\mathrm B}^{\mathrm{ell}}\ab(\kappa).
    \label{eq:iid-elliptical-bayes-ordering}
  \end{align}
  Nevertheless, their data-rich asymptotics agree including the leading
  coefficient:
  \begin{align}
    q_{\alpha,\mathrm B}\ab(\kappa)
    \sim
    q_{\alpha,\mathrm B}^{\mathrm{ell}}\ab(\kappa)
    \sim
    \frac{2^{-\alpha/2}}{\Gamma\ab(1+\alpha/2)}
    \frac{\sigma^\alpha}{\kappa}.
    \label{eq:iid-elliptical-bayes-leading-order}
  \end{align}

\label{prop:replica-stable-poisson-transformation}
Assume that \(\rho\) has finite \(\alpha\)-moment.
Let \(\{s_j\}_{j\geq1}\) be the Poisson process in \eqref{eq:appendix-positive-poisson-sequence}, ordered by decreasing size.
Independently draw \(g_j\overset{\mathrm{i.i.d.}}{\sim}\mathcal N(0,1)\) and \(\@ifstar\mathbf\boldsymbol v_j\overset{\mathrm{i.i.d.}}{\sim}\rho\).
The series \(\sum_j\sqrt{s_j}g_j\@ifstar\mathbf\boldsymbol v_j\) converges almost surely and
  \begin{align}
    \mathbb{E}\exp\ab(i\sum_j\sqrt{s_j}g_j\@ifstar\mathbf\boldsymbol k^\top\@ifstar\mathbf\boldsymbol v_j)
    &=\exp\ab\{-d_\alpha\int_0^\infty
      \mathbb{E}_{g,\@ifstar\mathbf\boldsymbol v}\ab[1-\cos(\sqrt{s}g\@ifstar\mathbf\boldsymbol k^\top\@ifstar\mathbf\boldsymbol v)]
      s^{-1-\alpha/2}\,\mathrm ds\ab\}
    \\
    &=\exp\ab\{-\int\mathrm d\@ifstar\mathbf\boldsymbol v\,\rho(\@ifstar\mathbf\boldsymbol v)
      \left|\@ifstar\mathbf\boldsymbol k^\top\@ifstar\mathbf\boldsymbol v\right|^{\alpha}\ab\}.
    \label{eq:replica-stable-poisson-transform}
  \end{align}

\label{prop:replica-scalar-reduction}
Define
\begin{align}
  F(h)
  &:=\min_{\{u_j\}}\ab\{
    \ell\ab(h+\sum_j\sqrt{s_j}g_ju_j-\epsilon)
    +\sum_j[\mathcal V_j(u_j)-\mathcal V_j(u_{j,*}(0))]\ab\}.
\end{align}
We have
\begin{align}
  F(h)
  &=\min_{v\in\mathbb{R}}\ab\{
    \ell(v)+(-\mathcal R)^*(\sqrt Q\xi-\epsilon+h-v)\ab\}.
  \label{eq:replica-factor-duality}
\end{align}

\begin{align}
  F(h)
  &=\min_{\{u_j\}}\sup_{p\in K_\ell}\ab\{
    (h-\epsilon)p-\ell^*(p)
    +\sum_j[\mathcal V_j(u_j)+\sqrt{s_j}g_jpu_j
             -\mathcal V_j(u_{j,*}(0))]\ab\}
  \\
  &=\sup_{p\in K_\ell}\ab\{
    (h-\epsilon)p-\ell^*(p)
    +\sum_j\ab[\min_u\{\mathcal V_j(u)+\sqrt{s_j}g_jpu\}
                   -\mathcal V_j(u_{j,*}(0))]\ab\}
  \\
  &=\sup_{p\in K_\ell}\ab\{
    (\sqrt Q\xi-\epsilon+h)p-\ell^*(p)+\mathcal R(p)\ab\}
  \\
  &=(\ell^*-\mathcal R)^*(\sqrt Q\xi-\epsilon+h)
  \\
  &=\min_{v\in\mathbb{R}}\ab\{
    \ell(v)+(-\mathcal R)^*(\sqrt Q\xi-\epsilon+h-v)\ab\}.
  \label{eq:replica-factor-dual-value}
\end{align}
Here the first equality uses \(\ell(r)=\sup_{p\in K_\ell}\{pr-\ell^*(p)\}\), the second formally interchanges the minimum and supremum and separates the minimizations over \(u_j\), the third uses the definitions of \(Q\), \(\xi\), and \(\mathcal R\), and the last two use the definition of the convex conjugate and the infimal-convolution identity.

Substituting the definition of \(\Phi_\kappa\) into
  Equation~\eqref{eq:data-rich-coefficient-stationarity} and dividing by
  \(\kappa^{1/\alpha}\) gives
  \begin{align}
    0
    &\in
    \frac{\lambda}{\kappa^{1/\alpha}}
    \partial\gamma\ab(w^*+u_{\kappa,*}(0))
    +\Phi_\kappa\ab(\kappa^{1/\alpha}u_{\kappa,*}(0)).
    \label{eq:data-rich-rescaled-root}
  \end{align}
  The finite convex regularizer has a
  locally bounded subdifferential.  Thus, for every $M<\infty$,
  \begin{align}
    \frac{\lambda}{\kappa^{1/\alpha}}
    \sup_{\left|u\right|\leq M}
    \sup_{s\in\partial\gamma(w^*+\kappa^{-1/\alpha}u)}
    \left|s\right|
    &\longrightarrow0.
    \label{eq:data-rich-regularizer-vanishes}
  \end{align}
  The local-uniform RS limit of $\Phi_\kappa$ makes the data term in
  Equation~\eqref{eq:data-rich-rescaled-root} remain of order one.
  Each $\Phi_\kappa$ is nondecreasing because it is the rescaled subgradient
  of the convex data contribution; its local-uniform limit $\Phi$ is
  therefore also nondecreasing.
  Since $\Phi$ is continuous and monotone with unique zero $U$, for every $\varepsilon>0$,
  \begin{align}
    \Phi\ab(U-\varepsilon)
    &<0<
    \Phi\ab(U+\varepsilon)
    \quad\text{almost surely}.
    \label{eq:data-rich-root-bracket}
  \end{align}
  The locally uniform $o(1)$ regularizer term preserves these signs in Equation~\eqref{eq:data-rich-rescaled-root}.  Monotonicity therefore implies that its zero lies between $U-\varepsilon$ and $U+\varepsilon$ with probability tending to one.
  Hence
  \begin{align}
    \kappa^{1/\alpha}u_{\kappa,*}\ab(0)
    &\xrightarrow{\mathrm d}
    U,
    \label{eq:data-rich-limiting-root}
  \end{align}
  where $U$ is the solution of $\Phi\ab(U)=0$.
  Taking the corresponding RS order-parameter limit gives convergence of the $\alpha$-moments:
  \begin{align}
    \kappa q_\alpha\ab(\kappa)
    &=
    \mathbb{E}\left|\kappa^{1/\alpha}u_{\kappa,*}(0)\right|^\alpha
    \longrightarrow
    \mathbb{E}\left|U\right|^\alpha
    =:c_\alpha.
    \label{eq:data-rich-moment-chain}
  \end{align}
  Hence
  \begin{align}
    q_\alpha\ab(\kappa)
    &=
    \frac{c_\alpha}{\kappa}
    +o\ab(\kappa^{-1}).
    \label{eq:data-rich-coefficient-scale-proof}
  \end{align}

  Proposition~\ref{prop:test-prediction-generalization} now gives
  \begin{align}
    \kappa^{1/\alpha}q_\alpha\ab(\kappa)^{1/\alpha}S_\alpha
    &=
    \ab(\kappa q_\alpha\ab(\kappa)\ab)^{1/\alpha}S_\alpha
    \xrightarrow{\mathrm d}
    c_\alpha^{1/\alpha}S_\alpha.
  \end{align}
  Since $\left|S_\alpha\right|$ has a finite positive median,
  \begin{align}
    \operatorname{median}\ab(
      q_\alpha\ab(\kappa)^{1/\alpha}\left|S_\alpha\right|
    \ab)
    &=
    q_\alpha\ab(\kappa)^{1/\alpha}
    \operatorname{median}\ab(\left|S_\alpha\right|)
    =
    \Theta\ab(\kappa^{-1/\alpha}).
  \end{align}
  The Gaussian fixed-point equations give $q_2^{\mathrm G}(\kappa)=c_2/\kappa+o(\kappa^{-1})$.
  Since $\left|S_2\right|$ also has a finite positive median,
  \begin{align}
    \operatorname{median}\ab(
      q_2^{\mathrm G}\ab(\kappa)^{1/2}\left|S_2\right|
    \ab)
    &=
    \Theta\ab(\kappa^{-1/2}).
  \end{align}
  This proves the median statements.

  For every fixed $t>0$, Equation~\eqref{eq:data-rich-coefficient-scale-proof} gives
  \begin{align}
    tq_\alpha\ab(\kappa)^{-1/\alpha}
    &=
    t\ab(\frac{\kappa}{c_\alpha})^{1/\alpha}
    \ab(1+o\ab(1))
    \longrightarrow\infty.
    \label{eq:data-rich-diverging-stable-threshold}
  \end{align}
  The stable-tail relation \(\Pr(\left|S_\alpha\right|>x)\sim Cx^{-\alpha}\) can therefore be applied at this threshold:
  \begin{align}
    \Pr\ab(
      q_\alpha\ab(\kappa)^{1/\alpha}\left|S_\alpha\right|>t
    )
    &=
    \Pr\ab(
      \left|S_\alpha\right|>
      tq_\alpha\ab(\kappa)^{-1/\alpha}
    )
    \\
    &\sim
    Cq_\alpha\ab(\kappa)t^{-\alpha}
    \\
    &\sim
    \frac{Cc_\alpha}{\kappa t^\alpha}.
  \end{align}
  This is Equation~\eqref{eq:data-rich-fixed-threshold-failure}.

  For Gaussian features, write
  \(S_2=\sqrt{2}Z\) with \(Z\sim\mathcal N(0,1)\).
  The standard Gaussian tail asymptotic gives
  \begin{align}
    \Pr\ab(
      q_2^{\mathrm G}\ab(\kappa)^{1/2}\left|S_2\right|>t
    )
    &\sim
    \frac{2\sqrt{q_2^{\mathrm G}\ab(\kappa)}}{t\sqrt\pi}
    \exp\ab(-\frac{t^2}{4q_2^{\mathrm G}\ab(\kappa)}).
  \end{align}
  Therefore
  \begin{align}
    \frac1\kappa
    \log\Pr\ab(
      q_2^{\mathrm G}\ab(\kappa)^{1/2}\left|S_2\right|>t
    )
    &=
    -\frac{t^2}{4\kappa q_2^{\mathrm G}\ab(\kappa)}
    +O\ab(\frac{\log\kappa}{\kappa})
    \longrightarrow
    -\frac{t^2}{4c_2},
  \end{align}
  which proves the Gaussian statement in Result~\ref{res:data-rich-tail-reliability}.
